def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd to not have trailing slash (except root)
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # If path is absolute, start from root; otherwise start from cwd
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')
        remaining = ''

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    # Move to parent
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Any other name is appended
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if candidate is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[candidate]

                # If target is absolute, start from root
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]
                        if current == '':
                            current = '/'
                    remaining = target

                # Process remaining components after resolving the link
                break
            else:
                current = candidate
        else:
            # All components processed without hitting a symlink
            break

        if not remaining or remaining == '/':
            # No more components to process
            break

    # Remove trailing slash (except for root)
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

